using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Windows.Forms;using Microsoft.Win32;
static class Uninstall {
 static string Root=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Seraphim"));
 static void RemoveKey(string path,string manifest){using(var key=Registry.CurrentUser.OpenSubKey(path)){if(key==null||!String.Equals(key.GetValue("") as string,manifest,StringComparison.OrdinalIgnoreCase))return;}Registry.CurrentUser.DeleteSubKey(path,false);}
 static void RemoveShortcut(string file){if(!File.Exists(file))return;Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);dynamic link=shell.CreateShortcut(file);string target=link.TargetPath as string;System.Runtime.InteropServices.Marshal.ReleaseComObject(link);System.Runtime.InteropServices.Marshal.ReleaseComObject(shell);if(target!=null&&Path.GetFullPath(target).StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))File.Delete(file);}
 [STAThread]static int Main(string[] args){try{if(!File.Exists(Path.Combine(Root,"installation-seraphim.txt"))||File.ReadAllText(Path.Combine(Root,"installation-seraphim.txt"))!="Seraphim.Share.0161")throw new IOException("Installation Seraphim non reconnue.");if(Process.GetProcessesByName("Seraphim").Any(p=>{try{return String.Equals(p.MainModule.FileName,Path.Combine(Root,"Seraphim.exe"),StringComparison.OrdinalIgnoreCase);}catch{return false;}}))throw new IOException("Quittez d’abord Seraphim depuis son icône près de l’horloge.");if(args.Length==0){if(MessageBox.Show("Supprimer Seraphim de ce PC ? Vos préférences et votre compte seront conservés. Les extensions se retirent séparément dans le navigateur.","Désinstaller Seraphim",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return 0;string helper=Path.Combine(Path.GetTempPath(),"Seraphim-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Application.ExecutablePath,helper);Process.Start(new ProcessStartInfo(helper,"--cleanup"){UseShellExecute=false,CreateNoWindow=true});return 0;}if(args.Length!=1||args[0]!="--cleanup")return 2;System.Threading.Thread.Sleep(800);string manifest=Path.Combine(Root,"native-host.json");foreach(string vendor in new[]{"Google\\Chrome","Chromium","Microsoft\\Edge"})RemoveKey("Software\\"+vendor+"\\NativeMessagingHosts\\com.seraphim.control",manifest);string start=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Seraphim");RemoveShortcut(Path.Combine(start,"Seraphim.lnk"));RemoveShortcut(Path.Combine(start,"Installation des extensions.lnk"));if(Directory.Exists(start)&&!Directory.EnumerateFileSystemEntries(start).Any())Directory.Delete(start);RemoveShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Seraphim.lnk"));using(var key=Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Seraphim")){if(key!=null&&String.Equals(key.GetValue("InstallLocation") as string,Root,StringComparison.OrdinalIgnoreCase)){key.Close();Registry.CurrentUser.DeleteSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Seraphim",false);}}Directory.Delete(Root,true);MessageBox.Show("Seraphim a été supprimé. Vos données personnelles sont conservées.","Seraphim");return 0;}catch(Exception ex){MessageBox.Show(ex.Message,"Seraphim",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
